            operator_extension,
            agent_extension_file,
            agent_model,
            agent_thinking,
            remote_cache_dir,
            model_swaps,
            speak_url,
            state_url,
            diagram_url,
            persona,
            env,
            activity_callback: None,
            route_callback: None,
            active_session: Arc::new(Mutex::new(None)),
            route: OPERATOR.into(),
            project: None,
